{
  "summary": "Test the ADAS forward-looking sensor system because ACC, forward collision and lane departure functions fail together with orange warning lamps after repeated dealer repair attempts.",
  "rationale": "The narrative reports that the forward-looking sensors fail, Adaptive Cruise Control with Full Stop and Forward Collision warning lamps turn orange, Cruise Control and Forward Collision fail, and Lane Departure Warnings stop working. The dealer has attempted repair three times. No rulebook entry matches these conditions, so the standard diagnostic test is proposed; the rearview camera recall is unrelated to the reported forward-looking sensor failures.",
  "group": "adas",
  "symptoms": [
    "forward looking sensors fail",
    "Adaptive Cruise Control and Forward Collision warning lamps turn orange",
    "Cruise Control fails",
    "Forward Collision fails",
    "Lane Departure Warnings stop working"
  ],
  "conditions": [
    "systems fail immediately when warning lamps appear",
    "The warning lamps do not appear prior to failure"
  ],
  "fault_codes": [],
  "safety_relevant": false,
  "targeted": false,
  "test_name": "standard ADAS diagnostic test",
  "clues": [
    {
      "kind": "symptom",
      "quote": "The forward looking sensors fail"
    },
    {
      "kind": "symptom",
      "quote": "Adaptive Cruise Control with Full Stop and Forward Collision warning lamps to blaze orange"
    },
    {
      "kind": "symptom",
      "quote": "Cruise Control immediately fails and Forward Collision also fails"
    },
    {
      "kind": "symptom",
      "quote": "Lane Departure Warnings stops working as well"
    },
    {
      "kind": "condition",
      "quote": "systems fail immediately when warning lamps appear"
    },
    {
      "kind": "condition",
      "quote": "The warning lamps do not appear prior to failure"
    },
    {
      "kind": "other",
      "quote": "The dealer has attempted to repair my vehicle 3 times"
    }
  ]
}

